import Foundation
import CryptoKit

enum CommandCatalog {
    static func validate(_ commands: [SavedConsoleCommand]) throws {
        guard commands.count <= 1000, Set(commands.map(\.id)).count == commands.count else { throw ConfigError.message("В библиотеке может быть до 1000 собственных команд с уникальными ID.") }
        for command in commands {
            if let error = SavedCommandSet(commands: [command]).validation { throw ConfigError.message(error) }
            guard command.shortcut == 0 else { throw ConfigError.message("Горячие клавиши назначаются отдельно для каждой записи.") }
        }
    }
    static func matches(_ command: SavedConsoleCommand, query: String, group: String = "") -> Bool {
        let text = [command.title, command.description, command.text, command.group].joined(separator: " ")
        return (group.isEmpty || command.group == group) && query.split(whereSeparator: \.isWhitespace).allSatisfy { text.localizedCaseInsensitiveContains(String($0)) }
    }
    static func copies(_ commands: [SavedConsoleCommand]) -> [SavedConsoleCommand] {
        commands.map { var copy = $0; copy.id = UUID(); copy.shortcut = 0; return copy }
    }
    // Read-only diagnostics. Nothing is assigned or sent to a session on initialization.
